/**
 * French dictionary — word lookup with IPA pronunciations.
 * Every word appearing in the French deck should have an entry.
 */

export interface DictEntry {
  en: string;   // English translation
  ipa: string;  // IPA pronunciation
  pos?: string; // Part of speech: n, v, adj, adv, prep, conj, det, pron
}

// ── Elision prefixes to strip ─────────────────────────────────
const ELISION_PREFIXES = ["qu'", "l'", "d'", "j'", "n'", "s'", "c'", "m'", "t'"];

// ── Main lookup function ──────────────────────────────────────
export function lookupWord(raw: string): DictEntry | null {
  // 1. Clean: lowercase, strip punctuation (but NOT apostrophes or hyphens initially)
  let clean = raw.toLowerCase().replace(/[¿¡.,!?;:"""\u2018\u2019()—–«»\d/]/g, '');
  if (!clean) return null;

  // 2. Direct match (preserves hyphens for compound words like après-midi)
  if (dictionary[clean]) return dictionary[clean];

  // 3. Handle elisions: l'homme → homme, j'ai → ai
  for (const prefix of ELISION_PREFIXES) {
    if (clean.startsWith(prefix)) {
      const remainder = clean.slice(prefix.length);
      if (dictionary[remainder]) return dictionary[remainder];
      // Try verb form reversal on remainder
      const inf = reverseVerb(remainder);
      if (inf && dictionary[inf]) return dictionary[inf];
      // Handle elision+hyphen combo: l'ai-je → ai-je → ai
      if (remainder.includes('-')) {
        const hbase = remainder.split('-')[0];
        if (dictionary[hbase]) return dictionary[hbase];
        const hinf = reverseVerb(hbase);
        if (hinf && dictionary[hinf]) return dictionary[hinf];
      }
    }
  }

  // Strip any remaining apostrophes
  clean = clean.replace(/'/g, '');
  if (dictionary[clean]) return dictionary[clean];

  // 4. Hyphenated compound words: try full match first, then base word
  if (clean.includes('-')) {
    // Full compound match already tried above; try base word for imperative pronouns: donnez-moi → donner
    const base = clean.split('-')[0];
    if (dictionary[base]) return dictionary[base];
    const inf = reverseVerb(base);
    if (inf && dictionary[inf]) return dictionary[inf];
    // Strip hyphens and continue with non-hyphenated form
    clean = clean.replace(/-/g, '');
    if (dictionary[clean]) return dictionary[clean];
  }

  // 5. Verb form reversal
  const inf = reverseVerb(clean);
  if (inf && dictionary[inf]) return dictionary[inf];

  // 6. Plural stripping
  if (clean.endsWith('aux')) {
    const singular = clean.slice(0, -3) + 'al';
    if (dictionary[singular]) return dictionary[singular];
  }
  if (clean.endsWith('s') && clean.length > 2) {
    const singular = clean.slice(0, -1);
    if (dictionary[singular]) return dictionary[singular];
  }
  if (clean.endsWith('x') && clean.length > 2) {
    const singular = clean.slice(0, -1);
    if (dictionary[singular]) return dictionary[singular];
  }

  // 7. Feminine → masculine: -euse → -eur, -ive → -if, -e → base
  if (clean.endsWith('euse')) {
    const masc = clean.slice(0, -4) + 'eur';
    if (dictionary[masc]) return dictionary[masc];
  }
  if (clean.endsWith('ive')) {
    const masc = clean.slice(0, -3) + 'if';
    if (dictionary[masc]) return dictionary[masc];
  }
  if (clean.endsWith('e') && clean.length > 3) {
    const masc = clean.slice(0, -1);
    if (dictionary[masc]) return dictionary[masc];
  }

  return null;
}

// ── Verb form → infinitive reversal ─────────────────────────
function reverseVerb(form: string): string | null {
  // -er verbs: present (-e, -es, -ons, -ez, -ent), past participle (-é)
  const erSuffixes = [
    ['ons', 'er'], ['ez', 'er'], ['ent', 'er'], ['es', 'er'], ['e', 'er'],
    ['é', 'er'], ['ée', 'er'], ['és', 'er'], ['ées', 'er'],
    ['ais', 'er'], ['ait', 'er'], ['aient', 'er'], ['ions', 'er'], ['iez', 'er'],
    ['ai', 'er'], ['as', 'er'], ['a', 'er'],
    ['erai', 'er'], ['eras', 'er'], ['era', 'er'], ['erons', 'er'], ['erez', 'er'], ['eront', 'er'],
    ['erais', 'er'], ['erait', 'er'], ['erions', 'er'], ['eriez', 'er'], ['eraient', 'er'],
  ];
  for (const [suffix, ending] of erSuffixes) {
    if (form.endsWith(suffix) && form.length > suffix.length + 1) {
      const candidate = form.slice(0, -suffix.length) + ending;
      if (dictionary[candidate]) return candidate;
    }
  }

  // -ir verbs (type 2 -iss-): -is, -it, -issons, -issez, -issent, -i
  const irSuffixes = [
    ['issons', 'ir'], ['issez', 'ir'], ['issent', 'ir'],
    ['issais', 'ir'], ['issait', 'ir'], ['issaient', 'ir'],
    ['is', 'ir'], ['it', 'ir'], ['i', 'ir'],
    ['irai', 'ir'], ['iras', 'ir'], ['ira', 'ir'], ['irons', 'ir'], ['irez', 'ir'], ['iront', 'ir'],
  ];
  for (const [suffix, ending] of irSuffixes) {
    if (form.endsWith(suffix) && form.length > suffix.length + 1) {
      const candidate = form.slice(0, -suffix.length) + ending;
      if (dictionary[candidate]) return candidate;
    }
  }

  // -re verbs: -s, -t, -ons, -ez, -ent, -u
  const reSuffixes = [
    ['ons', 're'], ['ez', 're'], ['ent', 're'],
    ['u', 're'], ['ue', 're'], ['us', 're'], ['ues', 're'],
    ['s', 're'],
  ];
  for (const [suffix, ending] of reSuffixes) {
    if (form.endsWith(suffix) && form.length > suffix.length + 2) {
      const candidate = form.slice(0, -suffix.length) + ending;
      if (dictionary[candidate]) return candidate;
    }
  }

  return null;
}

